script:
card({ name: "Connect Four", icon: 'grid', permissions: ['sound'] });
const words = {
  start: "Tap a column to drop the first counter",
  yourTurn: "Your turn",
  waiting: "Waiting for {p0}",
  someone: "the other player",
  youWon: "Four in a row. You won!",
  won: "{p0} won",
  draw: "The board is full: a draw",
  again: "New game",
  over: "The game is over",
  full: "Two people are already playing",
  notYours: "Not your turn",
  columnFull: "That column is full",
};

// Two players: the first to tap is red, the next person yellow.
const W = 7;
const H = 6;
const colors = { red: '#e5484d', yellow: '#f5c400' };

function init() {
  return { board: Array(W * H).fill(''), red: null, yellow: null, names: {}, turn: 'red', winner: null, last: -1, line: [] };
}

function at(b, c, r) {
  return c >= 0 && c < W && r >= 0 && r < H ? b[r * W + c] : '';
}

// The four (or more) in a row through column c, row r, if there are.
function fours(b, c, r) {
  const mark = at(b, c, r);
  for (const [dc, dr] of [[1, 0], [0, 1], [1, 1], [1, -1]]) {
    const cells = [r * W + c];
    for (const dir of [1, -1]) {
      let k = 1;
      while (at(b, c + dc * k * dir, r + dr * k * dir) === mark) {
        cells.push((r + dr * k * dir) * W + c + dc * k * dir);
        k++;
      }
    }
    if (cells.length >= 4) return cells;
  }
  return null;
}

on.drop = (s, args, ctx) => {
  if (s.winner) throw words.over;
  if (!s.red) s.red = ctx.author;
  else if (!s.yellow && ctx.author !== s.red) s.yellow = ctx.author;
  const color = ctx.author === s.red ? 'red' : ctx.author === s.yellow ? 'yellow' : null;
  if (!color) throw words.full;
  if (color !== s.turn) throw words.notYours;
  const c = Math.min(W - 1, Math.max(0, Math.floor(args.x * W)));
  let r = H - 1;
  while (r >= 0 && s.board[r * W + c]) r--;
  if (r < 0) throw words.columnFull;
  s.names[ctx.author] = ctx.authorName;
  s.board[r * W + c] = color;
  s.last = r * W + c;
  const line = fours(s.board, c, r);
  if (line) {
    s.winner = ctx.author;
    s.line = line;
    ctx.sound('win');
  } else if (s.board.every(m => m)) {
    s.winner = 'draw';
  } else {
    ctx.sound('tap');
  }
  s.turn = color === 'red' ? 'yellow' : 'red';
};

on.reset = () => init();

function view(s, me) {
  const next = s[s.turn];
  let status;
  if (s.winner === 'draw') status = words.draw;
  else if (s.winner) status = s.winner === me.id ? words.youWon : words.won.replace('{p0}', s.names[s.winner]);
  else if (!s.red) status = words.start;
  else if (next === me.id || (!next && me.id !== s.red)) status = words.yourTurn;
  else status = words.waiting.replace('{p0}', s.names[next] || words.someone);
  const shapes = [rect(0, 0, 1, 1, { fill: 'accent', round: 0.04 })];
  s.board.forEach((m, i) => {
    const style = { fill: m ? colors[m] : 'bg' };
    if (s.line.includes(i)) {
      style.stroke = 'fg';
      style.width = 4;
    } else if (i === s.last) {
      style.stroke = 'bg';
      style.width = 3;
    }
    shapes.push(circle((i % W + 0.5) / W, (Math.floor(i / W) + 0.5) / H, 0.4 / H, style));
  });
  return column([
    text(status, { bold: true, align: 'center', tone: s.winner === me.id ? 'success' : undefined }),
    canvas({ ratio: W / H, onTap: 'drop', shapes }),
    s.winner && button(words.again, 'reset', null, { tone: 'accent', align: 'center' }),
  ]);
}
